extends Resource
class_name DialogChoice

@export var label: String = ""
@export var next_id: StringName = &""
@export var condition_flag: StringName = &""

extends Resource
class_name DialogNode

@export var id: StringName = &""
@export var speaker: String = ""
@export var text: String = ""
@export var choices: Array[DialogChoice] = []
@export var next_id: StringName = &""

extends Resource
class_name DialogTree

@export var nodes: Array[DialogNode] = []
@export var start_id: StringName = &""

func get_node(node_id: StringName) -> DialogNode:
	for node in nodes:
		if node and node.id == node_id:
			return node
	return null

extends Node
class_name DialogPlayer

signal line_shown(speaker: String, text: String, choices_labels: Array)
signal dialog_finished

@export var tree: DialogTree

var current_node: DialogNode = null
var _flags: Dictionary = {}

func start() -> void:
	if not tree:
		emit_signal("dialog_finished")
		return
	_goto_node(tree.start_id)

func advance(choice_index: int = -1) -> void:
	if not current_node:
		emit_signal("dialog_finished")
		return

	if not current_node.choices.is_empty():
		var visible_choices = _get_visible_choices(current_node)
		if choice_index >= 0 and choice_index < visible_choices.size():
			var chosen = visible_choices[choice_index]
			_goto_node(chosen.next_id)
		else:
			# If there are choices but index is invalid, do nothing (wait for valid choice)
			return
	else:
		if current_node.next_id == &"":
			current_node = null
			emit_signal("dialog_finished")
		else:
			_goto_node(current_node.next_id)

func set_flag(name: StringName) -> void:
	_flags[name] = true

func has_flag(name: StringName) -> bool:
	return _flags.get(name, false)

func _get_visible_choices(node: DialogNode) -> Array[DialogChoice]:
	var visible_choices: Array[DialogChoice] = []
	for choice in node.choices:
		if choice:
			if choice.condition_flag == &"" or has_flag(choice.condition_flag):
				visible_choices.append(choice)
	return visible_choices

func _goto_node(node_id: StringName) -> void:
	if not tree:
		current_node = null
		emit_signal("dialog_finished")
		return

	var next_node = tree.get_node(node_id)
	if next_node:
		current_node = next_node
		_show_current_node()
	else:
		current_node = null
		emit_signal("dialog_finished")

func _show_current_node() -> void:
	if not current_node:
		emit_signal("dialog_finished")
		return

	var visible_choices = _get_visible_choices(current_node)
	var choice_labels: Array = []
	for choice in visible_choices:
		choice_labels.append(choice.label)

	emit_signal("line_shown", current_node.speaker, current_node.text, choice_labels)

extends Control

@export var dialog_player: DialogPlayer

@onready var speaker_label: Label = $SpeakerLabel
@onready var body_text_label: RichTextLabel = $BodyTextLabel
@onready var choice_container: VBoxContainer = $ChoiceContainer

func _ready() -> void:
	if dialog_player:
		dialog_player.line_shown.connect(_on_line_shown)
		dialog_player.dialog_finished.connect(_on_dialog_finished)

func _on_line_shown(speaker: String, text: String, choices_labels: Array) -> void:
	if speaker_label:
		speaker_label.text = speaker
	if body_text_label:
		body_text_label.text = text

	if choice_container:
		for child in choice_container.get_children():
			child.queue_free()

		if choices_labels.is_empty():
			var next_btn = Button.new()
			next_btn.text = "Next"
			if dialog_player:
				next_btn.pressed.connect(dialog_player.advance)
			choice_container.add_child(next_btn)
		else:
			for i in range(choices_labels.size()):
				var choice_label = choices_labels[i]
				var btn = Button.new()
				btn.text = choice_label
				if dialog_player:
					btn.pressed.connect(dialog_player.advance.bind(i))
				choice_container.add_child(btn)

func _on_dialog_finished() -> void:
	if speaker_label:
		speaker_label.text = ""
	if body_text_label:
		body_text_label.text = "[Dialogue Finished]"
	if choice_container:
		for child in choice_container.get_children():
			child.queue_free()
